// Formatting library for C++ - formatters for standard library types
//
// Copyright (c) 2012 - present, Victor Zverovich
// All rights reserved.
//
// For the license information refer to format.h.

#ifndef FMT_STD_H_
#define FMT_STD_H_

#include <atomic>
#include <bitset>
#include <cstdlib>
#include <exception>
#include <memory>
#include <thread>
#include <type_traits>
#include <typeinfo>
#include <utility>
#include <vector>

#include "format.h"
#include "ostream.h"

#if FMT_HAS_INCLUDE(<version>)
#  include <version>
#endif
// Checking FMT_CPLUSPLUS for warning suppression in MSVC.
#if FMT_CPLUSPLUS >= 201703L
#  if FMT_HAS_INCLUDE(<filesystem>)
#    include <filesystem>
#  endif
#  if FMT_HAS_INCLUDE(<variant>)
#    include <variant>
#  endif
#  if FMT_HAS_INCLUDE(<optional>)
#    include <optional>
#  endif
#endif

// GCC 4 does not support FMT_HAS_INCLUDE.
#if FMT_HAS_INCLUDE(<cxxabi.h>) || defined(__GLIBCXX__)
#  include <cxxabi.h>
// Android NDK with gabi++ library on some architectures does not implement
// abi::__cxa_demangle().
#  ifndef __GABIXX_CXXABI_H__
#    define FMT_HAS_ABI_CXA_DEMANGLE
#  endif
#endif

// Check if typeid is available.
#ifndef FMT_USE_TYPEID
// __RTTI is for EDG compilers. In MSVC typeid is available without RTTI.
#  if defined(__GXX_RTTI) || FMT_HAS_FEATURE(cxx_rtti) || FMT_MSC_VERSION || \
      defined(__INTEL_RTTI__) || defined(__RTTI)
#    define FMT_USE_TYPEID 1
#  else
#    define FMT_USE_TYPEID 0
#  endif
#endif

// For older Xcode versions, __cpp_lib_xxx flags are inaccurately defined.
#ifndef FMT_CPP_LIB_FILESYSTEM
#  ifdef __cpp_lib_filesystem
#    define FMT_CPP_LIB_FILESYSTEM __cpp_lib_filesystem
#  else
#    define FMT_CPP_LIB_FILESYSTEM 0
# endif
#endif

#ifndef FMT_CPP_LIB_VARIANT
#  ifdef __cpp_lib_variant
#    define FMT_CPP_LIB_VARIANT __cpp_lib_variant
#  else
#    define FMT_CPP_LIB_VARIANT 0
#  endif
#endif

#if FMT_CPP_LIB_FILESYSTEM
FMT_BEGIN_NAMESPACE

FMT_EXPORT
template <typename Char> struct formatter<std::filesystem::path, Char> {
 private:
  format_specs<Char> specs_;
  detail::arg_ref<Char> width_ref_;
  bool debug_ = false;

  template <typename FormatContext, typename PathChar>
  auto write_path(const std::filesystem::path& p, FormatContext& ctx,
                  format_specs<Char> specs, detail::arg_ref<Char> width_ref,
                  const std::basic_string<PathChar>& native) const
      -> decltype(ctx.out()) {
    switch (width_ref.kind) {
    case detail::arg_id_kind::none:
      break;
    case detail::arg_id_kind::index:
      specs.width = detail::get_dynamic_spec<detail::width_checker>(
          detail::get_arg(ctx, width_ref.val.index), ctx.error_handler());
      break;
    case detail::arg_id_kind::name:
      specs.width = detail::get_dynamic_spec<detail::width_checker>(
          detail::get_arg(ctx, width_ref.val.name), ctx.error_handler());
      break;
    }

    auto out = ctx.out();
    auto emit = [&](basic_string_view<Char> s) {
      auto data = s.data();
      auto size = s.size();
      if (specs.precision >= 0 && detail::to_unsigned(specs.precision) < size)
        size = detail::code_point_index(s, detail::to_unsigned(specs.precision));
      bool is_debug_type = specs.type == presentation_type::debug;
      size_t width = 0;
      if (specs.width != 0) {
        if (is_debug_type)
          width = detail::write_escaped_string(detail::counting_iterator{}, s)
                      .count();
        else
          width = detail::compute_width(basic_string_view<Char>(data, size));
      }
      return detail::write_padded(
          out, specs, size, width,
          [=](detail::reserve_iterator<decltype(out)> it) {
            if (is_debug_type) return detail::write_escaped_string(it, s);
            return detail::copy_str<Char>(data, data + size, it);
          });
    };

    if (p.empty()) return emit(basic_string_view<Char>());

    if (!debug_) {
      if constexpr (std::is_same_v<Char, char> &&
                    std::is_same_v<PathChar, wchar_t>) {
        auto converted = detail::to_utf8<wchar_t>(
            native, detail::to_utf8_error_policy::replace);
        return emit(converted);
      } else {
        auto converted = p.string<Char>();
        return emit(basic_string_view<Char>(converted));
      }
    }

    auto quoted = basic_memory_buffer<Char>();
    if constexpr (std::is_same_v<Char, char> &&
                  std::is_same_v<PathChar, wchar_t>) {
      auto buf = basic_memory_buffer<wchar_t>();
      detail::write_escaped_string<wchar_t>(std::back_inserter(buf), native);
      bool valid = detail::to_utf8<wchar_t>::convert(
          quoted, {buf.data(), buf.size()});
      FMT_ASSERT(valid, "invalid utf16");
    } else if constexpr (std::is_same_v<Char, PathChar>) {
      detail::write_escaped_string<std::filesystem::path::value_type>(
          std::back_inserter(quoted), native);
    } else {
      detail::write_escaped_string<Char>(std::back_inserter(quoted),
                                         p.string<Char>());
    }
    return emit(basic_string_view<Char>(quoted.data(), quoted.size()));
  }

 public:
  FMT_CONSTEXPR void set_debug_format(bool set = true) { debug_ = set; }

  template <typename ParseContext> FMT_CONSTEXPR auto parse(ParseContext& ctx) {
    auto it = ctx.begin(), end = ctx.end();
    if (it == end) return it;

    it = detail::parse_align(it, end, specs_);
    if (it == end) return it;

    it = detail::parse_dynamic_spec(it, end, specs_.width, width_ref_, ctx);
    if (it != end && *it == '?') {
      debug_ = true;
      ++it;
    }
    return it;
  }

  template <typename FormatContext>
  auto format(const std::filesystem::path& p, FormatContext& ctx) const {
    return write_path(p, ctx, specs_, width_ref_, p.native());
  }
};
FMT_END_NAMESPACE
#endif // FMT_CPP_LIB_FILESYSTEM

FMT_BEGIN_NAMESPACE
FMT_EXPORT
template <std::size_t N, typename Char>
struct formatter<std::bitset<N>, Char> : nested_formatter<string_view> {
 private:
  // Functor because C++11 doesn't support generic lambdas.
  struct writer {
    const std::bitset<N>& bs;

    template <typename OutputIt>
    FMT_CONSTEXPR OutputIt operator()(OutputIt out) {
      for (auto pos = N; pos > 0; --pos) {
        out = detail::write<Char>(out, bs[pos - 1] ? Char('1') : Char('0'));
      }

      return out;
    }
  };

 public:
  template <typename FormatContext>
  auto format(const std::bitset<N>& bs, FormatContext& ctx) const
      -> decltype(ctx.out()) {
    return write_padded(ctx, writer{bs});
  }
};

FMT_EXPORT
template <typename Char>
struct formatter<std::thread::id, Char> : basic_ostream_formatter<Char> {};
FMT_END_NAMESPACE

#ifdef __cpp_lib_optional
FMT_BEGIN_NAMESPACE
FMT_EXPORT
template <typename T, typename Char>
struct formatter<std::optional<T>, Char,
                 std::enable_if_t<is_formattable<T, Char>::value>> {
 private:
  formatter<T, Char> underlying_;
  static constexpr basic_string_view<Char> optional =
      detail::string_literal<Char, 'o', 'p', 't', 'i', 'o', 'n', 'a', 'l',
                             '('>{};

